-- Kontrola (powinno być 19 i 3):
SELECT sklep_id, count(*) AS oferty, min(price_numeric) AS od_zl, max(price_numeric) AS do_zl
FROM public.cultures WHERE sklep_id IN ('nomart.pl', 'jelux.pl') AND is_active GROUP BY sklep_id ORDER BY sklep_id;
